'use strict';

let workflowToolsPromise;
window.ensureWorkflowTools = () => {
  if (window.WorkflowTools) return Promise.resolve(window.WorkflowTools);
  if (!workflowToolsPromise) {
    workflowToolsPromise = new Promise((resolve, reject) => {
      const script = document.createElement('script');
      script.src = '/static/vendor/workflow-tools/workflow-tools.js';
      script.onload = () => {
        if (window.WorkflowTools) resolve(window.WorkflowTools);
        else { script.remove(); workflowToolsPromise = null; reject(new Error('Workflow tools did not initialize.')); }
      };
      script.onerror = () => { script.remove(); workflowToolsPromise = null; reject(new Error('Unable to load workflow tools.')); };
      document.head.appendChild(script);
    });
  }
  return workflowToolsPromise;
};

