function remainingOrderQuantity(qty,filled){
  if(!/^\d+(?:\.\d+)?$/.test(String(qty??''))||!/^\d+(?:\.\d+)?$/.test(String(filled??'')))return null;
  const parts=[String(qty).split('.'),String(filled).split('.')],scale=Math.max(...parts.map(p=>(p[1]||'').length));
  const [total,done]=parts.map(p=>BigInt(p[0]+(p[1]||'').padEnd(scale,'0'))),remaining=total-done;
  if(remaining<0n)return null;
  const digits=remaining.toString().padStart(scale+1,'0');
  return scale?digits.slice(0,-scale)+'.'+digits.slice(-scale):digits;
}
function provenPackage(row){return row.order_class==='mleg'&&row.package_mapping?.parent_id===row.id&&row.package_mapping?.basis==='actual_nested_members_and_exact_retained_terms'&&Array.isArray(row.package_mapping.leg_ids)&&row.package_mapping.leg_ids.length>=2&&row.package_mapping.leg_ids.length<=4&&new Set(row.package_mapping.leg_ids).size===row.package_mapping.leg_ids.length&&row.package_terms?.order_class==='mleg'&&row.package_terms.session==='regular'&&row.package_terms.legs?.length===row.package_mapping.leg_ids.length;}
function brokerExposureUnknown(row){return row.exposure_status==='unknown'||!provenPackage(row)&&Boolean(row.asset_class&&row.asset_class!=='us_equity');}
