async function evaluationAction(action,id){
 if(evaluationBusy)return;evaluationBusy=true;evaluationError='';render();
 try{
  if(action==='load')evaluationSources=await api('/api/evaluations');
  else if(action==='open')evaluationItem=await api('/api/evaluations?id='+encodeURIComponent(id));
  else if(action==='preview'){
   if(!evaluationDraft.reviewed)throw new Error('Review the scenario assumptions before saving a preview.');
   if(evaluationDraft.random_seed.trim()===''||evaluationDraft.latency_ns.trim()==='')throw new Error('Enter an explicit seed and latency.');
   const proposal=evaluationSources?.proposals.find(p=>p.id===evaluationDraft.proposal_id);
   if(!proposal)throw new Error('Choose an existing saved plan revision.');
   strategyView='results';evaluationItem=await api('/api/evaluations',{...evaluationDraft,action:'preview',proposal_revision:proposal.revision,currency:'USD',currency_basis:'declared_simulation_assumption',starting_holdings:[],submission_model:'after_first_completed_bar',end_positions:'leave_open',actual_fees:'unknown',bar_path:'open_high_low_close',random_seed:Number(evaluationDraft.random_seed),latency_ns:Number(evaluationDraft.latency_ns)});
  }else if(action==='run'){
   if(!evaluationItem?.preview||evaluationItem.status!=='preview')throw new Error('Save and review an unchanged preview first.');
   evaluationItem=await api('/api/evaluations',{action:'run',id:evaluationItem.id,spec_sha256:evaluationItem.spec_sha256});
  }
  if(evaluationSources&&action!=='load')evaluationSources=await api('/api/evaluations');
 }catch(error){evaluationError=error.message;}
 finally{evaluationBusy=false;if(activePage==='strategy')render();}
 clearTimeout(evaluationTimer);
 if(!evaluationError&&['queued','running'].includes(evaluationItem?.status)){const identity=evaluationItem.id;evaluationTimer=setTimeout(()=>evaluationAction('open',identity),5000);}
}
