let experimentDraft={history_key:'',benchmark_history_key:'',start_at:'',end_at:'',starting_cash:'',decision_basis:'hindsight_scenario',window:{mode:'rolling',train_sessions:'126',validation_sessions:'21',gap_sessions:'1',oos_sessions:'21',step_sessions:'21'},search:{mode:'grid',seed:'0',max_trials:'64'},selection:{objective:'',direction:'',secondary_metric:'',secondary_direction:'',minimum_closed_trades:''},budgets:{max_native_runs:'',experiment_seconds:'',trial_seconds:'',no_experiment_time_cap:false,no_trial_time_cap:false},scenarios:[experimentScenario()]};
function experimentField(path,label,value,choices=null){
 const attr='id="experiment-'+path.replaceAll('.','-')+'" data-experiment-field="'+path+'"';
 return '<label>'+esc(label)+(choices?'<select '+attr+'><option value="">Choose explicitly</option>'+choices.map(choice=>'<option value="'+esc(choice)+'" '+(String(value)===String(choice)?'selected':'')+'>'+esc(choice)+'</option>').join('')+'</select>':'<input '+attr+' value="'+esc(value??'')+'">')+'</label>';
}
function experimentHistoryField(path,label,symbol=''){
 const rows=(experimentSource?.histories||[]).filter(h=>!symbol||h.symbol===symbol),reason=h=>h.adjustment!=='raw'?'Requires raw adjustment':h.complete!==true||h.pagination_complete!==true?'Incomplete retained history':h.error?'Source error: '+h.error:'';
 return '<label>'+esc(label)+'<select id="experiment-request-'+path+'" data-experiment-field="request.'+path+'"><option value="">'+(path==='benchmark_history_key'?'No benchmark':'Choose complete raw daily history')+'</option>'+rows.map(h=>'<option value="'+esc(h.key)+'" '+(experimentDraft[path]===h.key?'selected':'')+' '+(reason(h)?'disabled':'')+'>'+esc(h.symbol+' · '+h.start+' to '+h.end+' · '+h.adjustment+' · captured '+h.captured_at+' · '+(reason(h)||'Source selection available; preview checks remain')+' · '+h.key)+'</option>').join('')+'</select></label><p>'+esc(rows.some(h=>!reason(h))?'Preview verifies exact artifacts, calendar, window and strategy compatibility.':'No complete raw daily receipt is available for this selection. Adjusted or incomplete sources cannot be used for this experiment.')+'</p>';
}
function experimentOperand(path,operand,quantity=false,priceOnly=false){
 const f=(key,label,choices)=>experimentField(path+'.'+key,label,operand[key],choices);
 return '<fieldset><legend>'+esc(quantity?'Quantity · whole shares':path.startsWith('execution.')?({'execution.limit_price':'Entry limit price','execution.stop_price':'Entry stop trigger','execution.exit_plan.take_profit':'Linked take-profit limit','execution.exit_plan.stop_price':'Linked protective stop trigger','execution.exit_plan.stop_limit_price':'Linked protective stop limit'}[path]||'Decision-frozen price'):path.endsWith('left')?'Left series/value':'Right series/value')+'</legend>'+f('kind','Operand kind',quantity?['constant','parameter']:['price','indicator','constant','parameter'])+(operand.kind==='price'?f('field','Recorded field',['open','high','low','close']):operand.kind==='indicator'?f('name','Indicator',priceOnly?experimentIndicators.filter(name=>!['rsi','mfi'].includes(name)):experimentIndicators):operand.kind==='parameter'?f('name','Finite parameter name',experimentStrategy.parameters.map(p=>p.name).filter(Boolean))+f('units','Units',quantity?['shares']:priceOnly?['price']:['price','0-100','0-1','shares']):f('value','Exact decimal value')+f('units','Units',quantity?['shares']:priceOnly?['price']:['price','0-100','0-1','shares']))+'</fieldset>';
}

function experimentExecutionMarkup(){
 const x=experimentExecution,plan=x.exit_plan;
 return '<fieldset><legend>Decision-frozen entry and linked protection</legend>'+experimentField('execution.entry_order_type','Entry order type',x.entry_order_type,['MARKET','LIMIT','STOP_LIMIT'])+experimentField('execution.time_in_force','Duration',x.time_in_force,['DAY','GTC'])+(x.entry_order_type!=='MARKET'?experimentOperand('execution.limit_price',x.limit_price||{kind:'price',field:'close'},false,true):'')+(x.entry_order_type==='STOP_LIMIT'?experimentOperand('execution.stop_price',x.stop_price||{kind:'price',field:'close'},false,true):'')+'<p>All applicable prices freeze from the completed signal bar: exact positive USD cents, no rounding. LIMIT uses a fixed limit; STOP_LIMIT needs separate trigger and limit. MARKET has no price cap.</p>'+[['take_profit','Linked take-profit limit'],['stop_price','Linked protective stop'],['stop_limit_price','Protective stop limit · requires stop']].map(([key,label])=>'<label><input type="checkbox" data-experiment-protection="'+key+'" '+(plan?.[key]?'checked':'')+' '+(key==='stop_limit_price'&&!plan?.stop_price?'disabled':'')+'> '+label+'</label>'+(plan?.[key]?experimentOperand('execution.exit_plan.'+key,plan[key],false,true):'')).join('')+'<p>Native FULL-entry activation: a partial entry may remain unprotected. Rule exit cancels a working entry and its live protection, waits for actual terminal events and late-fill reconciliation, then exits actual residual holdings with MARKET. No pyramiding or duplicate exits.</p><p>Selected timing: native OHLC-path next modeled open. Public TradeTickDataWrangler uses fixed 100 ms compressed OHLC offsets, seed None; native bar execution is off and trade execution is on. A close tick precedes the completed bar; the next generated open tick updates the book before a queued intent. These are modeled events, not actual session opens, ticks, BBO or liquidity. DAY uses the declared session boundary. Exact converter, volume allocation/floor, precision, flags and source identity are retained in the preview.</p></fieldset>';
}

function experimentRule(name){
 const rule=experimentStrategy[name];return '<fieldset><legend>'+esc(name==='entry'?'Entry rule':'Exit rule')+'</legend>'+experimentField('strategy.'+name+'.operator','Combine conditions',rule.operator,['ALL','ANY'])+rule.atoms.map((atom,index)=>'<article><h4>Condition '+(index+1)+'</h4>'+experimentOperand('strategy.'+name+'.atoms.'+index+'.left',atom.left)+experimentField('strategy.'+name+'.atoms.'+index+'.comparison','Comparison',atom.comparison,['above','below','cross_above','cross_below'])+experimentOperand('strategy.'+name+'.atoms.'+index+'.right',atom.right)+'<button data-experiment-remove-atom="'+name+':'+index+'" '+(rule.atoms.length===1?'disabled':'')+'>Remove condition</button></article>').join('')+'<button data-experiment-add-atom="'+name+'" '+(rule.atoms.length>=16?'disabled':'')+'>Add condition</button></fieldset>';
}
function experimentDetail(label,value,open=false){return '<details '+(open?'open':'')+'><summary>'+esc(label)+'</summary><pre>'+esc(JSON.stringify(value??null,null,2))+'</pre></details>';}
function experimentTable(rows){
 if(!Array.isArray(rows)||!rows.length)return '<p>No comparison rows retained.</p>';
 const fields=[...new Set(rows.flatMap(row=>Object.keys(row)))];return '<div class="table-scroll"><table><thead><tr>'+fields.map(key=>'<th>'+esc(key.replaceAll('_',' '))+'</th>').join('')+'</tr></thead><tbody>'+rows.map(row=>'<tr>'+fields.map(key=>'<td>'+(row[key]!==null&&typeof row[key]==='object'?experimentDetail('Details',row[key]):esc(row[key]??'Unavailable'))+'</td>').join('')+'</tr>').join('')+'</tbody></table></div>';
}

function experimentCurves(series){
 const curves=series.filter(s=>Array.isArray(s.points)&&s.points.length),points=curves.flatMap(s=>s.points).filter(p=>p&&Number.isFinite(Date.parse(p.at))&&p.equity!==null&&p.equity!==''&&Number.isFinite(Number(p.equity)));
 if(!points.length)return '<p>No retained dated OOS equity curve is available. No curve is fabricated.</p>';
 const times=points.map(p=>Date.parse(p.at)),values=points.map(p=>Number(p.equity)),xmin=times.reduce((a,b)=>Math.min(a,b),Infinity),xmax=times.reduce((a,b)=>Math.max(a,b),-Infinity),ymin=values.reduce((a,b)=>Math.min(a,b),Infinity),ymax=values.reduce((a,b)=>Math.max(a,b),-Infinity),x=t=>45+(t-xmin)/(xmax-xmin||1)*710,y=v=>235-(v-ymin)/(ymax-ymin||1)*210,colors=['#86d6ab','#e6c17d','#a5b3c0','#dc8995','#90b9e0'];
 return '<figure><figcaption>Out-of-sample modeled equity / USD · common actual UTC time axis. Separate fold/scenario paths, no compounding or rebasing. Exact values remain below.</figcaption><div class="experiment-curve-scroll"><svg class="experiment-equity-curve" viewBox="0 0 800 275" role="img" aria-label="Aligned retained out-of-sample modeled equity curves"><line x1="45" x2="755" y1="235" y2="235" stroke="currentColor"/>'+curves.map((s,index)=>{let path='',prior=null;for(const point of s.points){const t=Date.parse(point?.at),v=point?.equity;if(v===null||v===undefined||v===''||!Number.isFinite(t)||!Number.isFinite(Number(v))||prior!==null&&t<=prior){prior=null;continue;}path+=(prior===null?'M':'L')+x(t).toFixed(2)+','+y(Number(v)).toFixed(2)+' ';prior=t;}return '<path d="'+path+'" fill="none" stroke="'+colors[index%colors.length]+'" '+(s.benchmark?'stroke-dasharray="5 4"':'')+'><title>'+esc(s.label)+'</title></path>';}).join('')+'<text x="45" y="260" fill="currentColor" font-size="10">'+esc(new Date(xmin).toISOString())+'</text><text x="755" y="260" text-anchor="end" fill="currentColor" font-size="10">'+esc(new Date(xmax).toISOString())+'</text><text x="0" y="25" fill="currentColor" font-size="10">'+esc(ymax)+'</text><text x="0" y="235" fill="currentColor" font-size="10">'+esc(ymin)+'</text></svg></div><ul>'+curves.map((s,index)=>'<li><span style="color:'+colors[index%colors.length]+'">'+esc(s.label)+'</span> · '+s.points.length+' retained observations</li>').join('')+'</ul>'+experimentDetail('Exact dated modeled equity and benchmark observations',curves)+'</figure>';
}
function experimentResultCurves(result,label=''){
 const curves=[];for(const fold of result?.folds||[])for(const scenario of fold.oos?.scenarios||[]){const r=scenario.result;if(!r)continue;const name=label+' · fold '+fold.id+' · '+scenario.scenario_id;curves.push({label:name,points:r.equity_curve});if(Array.isArray(r.benchmark_curve))curves.push({label:name+' · retained benchmark',points:r.benchmark_curve,benchmark:true});}return curves;
}
function experimentEvents(item){return '<h4>Retained native evidence and progress</h4>'+(item.events?.length?'<table><thead><tr><th>Ordinal</th><th>Event</th><th>Fold / trial / scenario</th><th>Exact evidence</th></tr></thead><tbody>'+item.events.map(e=>'<tr><td>'+esc(e.ordinal)+'</td><td>'+esc(e.type)+'</td><td>'+esc([e.fold_id,e.trial_id,e.phase,e.scenario_id].filter(Boolean).join(' / '))+'</td><td><button data-experiment-event="'+esc(e.id)+'">Open retained event</button></td></tr>').join('')+'</tbody></table>':'<p>No execution events retained for this preview.</p>');}

function experimentMetricRows(rows){return rows.map(({metrics,...row})=>({...row,'Net return (%)':metrics?.net_return_pct??'Unavailable','Modeled P&L':metrics?.total_pnl??'Unavailable','Maximum drawdown (%)':metrics?.max_drawdown_pct??'Unavailable','Closed trades':metrics?.closed_trades??'Unavailable'}));}
function experimentResults(item){
 const result=item?.result;if(!result)return '';
 return '<h3>Retained experiment execution · '+esc(simulationLabel(result.status||item.status))+'</h3><p>Analytical outcome: '+esc(result.analytical_outcome==='no_qualifier'?'Finished — no eligible strategy':result.analytical_outcome==='selection_gaps'?'Finished — selection gaps':result.analytical_outcome||'Not reported')+'. Negative OOS performance is a result, not a reason to reselect. A fold without selection has no performed OOS.</p>'+experimentTable([result.counts||{}])+experimentTable(result.reasons)+'<p>Native runs: '+esc(result.native_runs??'Unavailable')+'. Fold outcomes are separate modeled scenarios. No synthetic compounded chain or actual account performance is inferred.</p>'+experimentTable(experimentMetricRows(result.comparison||[]))+experimentCurves(experimentResultCurves(result,item.id))+experimentDetail('Coverage, optimizer and limitations',{coverage:result.coverage,optimizer:result.optimizer,limitations:result.limitations})+(result.folds||[]).map(fold=>'<article><h4>Fold '+esc(fold.id)+' · '+esc(fold.status)+'</h4><p>Selected trial '+esc(fold.selected_trial_id??'None')+' · '+esc(fold.reason||'')+'</p>'+experimentDetail('Train / validation selection and untouched out-of-sample evidence',fold)+'</article>').join('')+experimentTable(experimentMetricRows((result.trials||[]).flatMap(trial=>['train','validation'].map(phase=>({fold:trial.fold_id,trial:trial.trial_id,parameters:trial.parameters,phase,status:trial[phase]?.status,eligible:trial.eligible,metrics:trial[phase]?.metrics})))))+experimentDetail('Exact terminal result, native reports and source references',result);
}

function experimentPreview(preview){
 if(!preview)return '<p>Immutable preview evidence is unavailable.</p>';
 return '<h4>Bound experiment</h4><p>Strategy '+esc(preview.strategy?.name)+' revision '+esc(preview.strategy?.revision)+' · '+esc(preview.strategy?.symbol)+' · strategy SHA '+esc(preview.strategy_sha256)+'</p>'+experimentTable([preview.preview_counts||{}])+experimentDetail('Bound converter/path, source identity, volume, precision and execution flags',{execution:preview.strategy?.execution,representation:preview.representation,conversion:preview.conversion,data_availability:preview.data_availability,input_artifacts:preview.input_artifacts})+'<h4>Exact fold windows and warmup</h4>'+experimentTable((preview.folds||[]).flatMap(fold=>['train','validation','oos'].map(phase=>({fold:fold.id,phase,start:fold[phase]?.start_at,end:fold[phase]?.end_at,scored_sessions:fold[phase]?.scored_sessions,warmup_sessions:fold[phase]?.warmup_sessions}))))+'<h4>Cost/fill scenarios</h4>'+experimentTable(preview.request?.scenarios)+'<h4>'+esc(preview.candidates?'Complete grid trial manifest':'Bound adaptive search configuration')+'</h4>'+(preview.candidates?experimentTable(preview.candidates):experimentDetail('Sampler, pruner, seed, search space and stopping rules',{optimizer:preview.optimizer,domains:preview.strategy?.parameters,search:preview.request?.search,budgets:preview.request?.budgets}))+experimentDetail('Exact immutable specification, source evidence and limitations',preview);
}
function experimentComparisonMarkup(item){
 const comparison=item?.comparison;if(!comparison)return experimentDetail('Comparison evidence unavailable',item);
 return '<h3>Side-by-side retained experiments</h3><p>'+esc(comparison.basis)+'</p>'+experimentTable(experimentMetricRows((comparison.rows||[]).flatMap(row=>(row.comparison||[]).map(value=>({experiment_id:row.experiment_id,status:row.status,...value})))))+experimentCurves((comparison.rows||[]).flatMap(row=>experimentResultCurves({folds:row.folds},row.experiment_id)))+experimentTable((comparison.rows||[]).map(row=>({experiment_id:row.experiment_id,status:row.status,coverage:row.coverage})))+experimentDetail('Immutable member references and exact comparison evidence',comparison);
}

function experimentMarkup(){
 const terminal=!!experimentItem?.result&&!['preview','queued','running','cancelling'].includes(experimentItem.status);
 const source=experimentSource,strategies=source?.strategies||[],items=(source?.items||[]).filter(item=>item.kind==='experiment'),comparisons=(source?.items||[]).filter(item=>item.kind==='experiment_comparison'),f=(path,label,choices)=>experimentField('request.'+path,label,path.split('.').reduce((v,k)=>v?.[k],experimentDraft),choices);
 const cap=source?.capabilities,unavailable=cap?.optimizer?.available!==true;
 return '<section class="panel journal-workspace" id="strategy-experiments"><fieldset '+(experimentBusy?'disabled':'')+'><h2>Reusable strategy experiments</h2><p>Retained daily data · isolated native simulation · whole-share USD equity and empty starting holdings. Closed-bar signals use a separately specified later execution event; results are modeled hindsight, not live or broker fills.</p><button id="experiment-load" '+(experimentBusy?'disabled':'')+'>Load strategies, retained data and experiment capability</button><p role="status">'+esc(experimentError||(experimentBusy?'Working…':experimentItem?.status||'No experiment selected'))+'</p>'+(source?experimentDetail('Installed capability and supported profile',cap)+'<p>'+esc(unavailable?(cap?.optimizer?.reason||'Required optional optimizer is unavailable; preview remains available but Run is disabled.'):'Required optimizer is available; runtime/profile and data validation remain separate.')+'</p><div data-strategy-panel="strategies"><h3>Saved strategies</h3><label>Saved strategy revision<select id="experiment-strategy"><option value="">New strategy</option>'+strategies.map(row=>{const s=row.definition;return '<option value="'+esc(s.id)+'" '+(s.id===experimentStrategyId?'selected':'')+'>'+esc(s.name+' · '+s.symbol+' · revision '+s.revision)+'</option>';}).join('')+'</select></label><div class="proposal-fields">'+experimentField('strategy.name','Strategy name',experimentStrategy.name)+experimentField('strategy.symbol','One equity symbol',experimentStrategy.symbol)+experimentOperand('strategy.quantity',experimentStrategy.quantity,true)+'</div><h4>Finite typed parameter domains</h4><p>Exact decimal strings; comma-separated finite values. Integer quantities must remain positive whole shares. No scripts, expressions or imports execute.</p>'+experimentStrategy.parameters.map((p,index)=>'<fieldset>'+experimentField('strategy.parameters.'+index+'.name','Parameter name',p.name)+experimentField('strategy.parameters.'+index+'.type','Type',p.type,['integer','decimal'])+experimentField('strategy.parameters.'+index+'.values','Exact values, comma-separated',p.values)+'<button data-experiment-remove-parameter="'+index+'">Remove parameter</button></fieldset>').join('')+'<button id="experiment-add-parameter">Add finite parameter</button>'+experimentRule('entry')+experimentRule('exit')+experimentExecutionMarkup()+'<button id="experiment-save-strategy" '+(experimentBusy||!experimentExecution?'disabled':'')+'>Save strategy '+(experimentStrategyId?'new revision':'definition')+'</button><p>'+esc(experimentStrategyDirty?'Unsaved strategy edits; save a new revision before preview.':'Saved strategy revision '+experimentStrategyRevision+' selected.')+'</p></div><div data-strategy-panel="setup"><h3>Configure the experiment</h3><p>Selected strategy: '+esc(experimentStrategy.name||'None')+' · revision '+esc(experimentStrategyRevision??'Not saved')+'. Choose or edit a revision in Saved strategies.</p>'+(experimentBranch?'<p>New branch of '+esc(experimentBranch.id)+' · parent spec '+esc(experimentBranch.spec_sha256)+'. Retained cache selectors are explicit; the new preview records actual selected artifact hashes.</p>':'')+''+experimentHistoryField('history_key','Exact retained history receipt',experimentStrategy.symbol)+experimentHistoryField('benchmark_history_key','Optional retained benchmark receipt')+'<div class="proposal-fields">'+f('start_at','Window start · ISO timestamp with timezone')+f('end_at','Window end · ISO timestamp with timezone')+f('starting_cash','Scenario starting cash / USD')+f('decision_basis','Strategy availability basis',['recorded_decision','hindsight_scenario'])+'</div><p>If history or benchmark capture follows the window start, explicitly choose hindsight. Recorded decision mode cannot establish point-in-time availability from later capture.</p><h4>Walk-forward windows</h4>'+f('window.mode','Training mode',['rolling','expanding'])+['train_sessions','validation_sessions','gap_sessions','oos_sessions','step_sessions'].map(key=>f('window.'+key,key.replaceAll('_',' '))).join('')+'<p>Counts and both gaps use expected calendar sessions; missing sessions are not compressed. A clock-duration embargo is unavailable. Gaps separate training, validation and untouched OOS. Dynamic warmup does not trade; folds reset independently. Boundary orders cancel and retained positions are marked, not artificially closed.</p><h4>Search and selection</h4>'+f('search.mode','Search mode',['grid','adaptive'])+f('search.seed','Sampler seed')+f('search.max_trials','Maximum trials / adaptive asks per outer fold')+'<p>Grid enumerates the complete finite grid or rejects an insufficient budget. Adaptive uses TPESampler and NopPruner; the default 64 asks includes failures and repeated selections. Full matching fingerprints may reuse a retained source trial and must disclose it.</p>'+f('selection.objective','Objective',experimentMetrics)+f('selection.direction','Direction',['maximize','minimize'])+f('selection.secondary_metric','Secondary tie-break metric',experimentMetrics)+f('selection.secondary_direction','Secondary direction',['maximize','minimize'])+f('selection.minimum_closed_trades','Minimum closed trades required in training and validation · whole number, at least 1')+'<p>Both training and validation must meet the minimum closed-trade eligibility. Stable parameter identity breaks remaining ties. No qualifying candidate means no winner; failed/missing results are not zero returns.</p><h4>Explicit budgets</h4>'+f('budgets.max_native_runs','Maximum native runs')+['experiment','trial'].map(kind=>f('budgets.'+kind+'_seconds',kind+' deadline / seconds')+'<label><input type="checkbox" data-experiment-field="request.budgets.no_'+kind+'_time_cap" '+(experimentDraft.budgets['no_'+kind+'_time_cap']?'checked':'')+'> Explicitly no '+kind+' time cap</label>').join('')+'<h4>Cost and fill scenarios</h4>'+experimentDraft.scenarios.map((s,index)=>'<fieldset><legend>Scenario '+(index+1)+'</legend>'+['id','fee_usd','fee_per','limit_fill_probability','slippage_probability','random_seed'].map(key=>experimentField('request.scenarios.'+index+'.'+key,key.replaceAll('_',' ')+(key==='fee_usd'?' / USD · enter zero explicitly':''),s[key],key==='fee_per'?['order','fill']:null)).join('')+'<p>Latency is 0 ns for this declared profile. Fees, fill probabilities and slippage are assumptions; actual fees remain unknown.</p><button data-experiment-remove-scenario="'+index+'" '+(experimentDraft.scenarios.length===1?'disabled':'')+'>Remove scenario</button></fieldset>').join('')+'<button id="experiment-add-scenario">Add scenario</button><p>Preview saves exact strategy/data/fold/scenario/search/cost identities; it does not run evaluation or collect data.</p><button id="experiment-preview" '+(experimentBusy||!experimentExecution||!experimentStrategyId||experimentStrategyDirty?'disabled':'')+'>Save immutable experiment preview</button></div>':'')+'<div data-strategy-panel="results">'+(experimentItem?(terminal?experimentResults(experimentItem):'')+'<h3>Review this exact experiment</h3><p>Experiment '+esc(experimentItem.id)+' · '+esc(experimentItem.status)+' · spec '+esc(experimentItem.spec_sha256)+' · '+esc(experimentDirty?'Editor changed; save a new preview before Run.':'Exact saved preview selected.')+'</p>'+(terminal?'<details><summary>Saved experiment preview</summary>'+experimentPreview(experimentItem.preview)+'</details>':experimentPreview(experimentItem.preview))+'<button id="experiment-run" '+(experimentBusy||experimentDirty||experimentItem.status!=='preview'||unavailable||!experimentExecution?'disabled':'')+'>Run this exact experiment</button>'+(['queued','running','cancelling'].includes(experimentItem.status)?'<button id="experiment-cancel" '+(experimentBusy?'disabled':'')+'>Request cancellation</button>':'')+'<button id="experiment-edit-branch" '+(experimentBusy?'disabled':'')+'>Edit configuration as a new branch</button><button id="experiment-repeat" '+(experimentBusy?'disabled':'')+'>Create a separate repeat / branch preview</button><p>A repeat receives a new ID and requires explicit Run. Exact resume, pruning, carry, overlapping OOS and wider asset/order profiles remain unavailable.</p>'+(terminal?'':experimentResults(experimentItem))+experimentEvents(experimentItem)+(experimentEvent?experimentDetail('Exact retained native event and reports',experimentEvent,true):''):'')+'</div><div data-strategy-panel="runs">'+(source?'<h3>Saved experiments and comparison</h3>'+items.map(item=>'<article><label><input type="checkbox" data-experiment-compare="'+esc(item.id)+'" '+(experimentCompared.has(item.id)?'checked':'')+'> Compare</label><button data-experiment-open="'+esc(item.id)+'">'+esc(item.id+' · '+item.status)+'</button><p>'+esc(item.spec_sha256||'')+'</p></article>').join('')+'<button id="experiment-compare" '+(experimentBusy||experimentCompared.size<2?'disabled':'')+'>Compare selected retained experiments</button><h4>Saved comparisons</h4>'+comparisons.map(item=>'<button data-experiment-open="'+esc(item.id)+'">Open comparison '+esc(item.id)+'</button>').join('')+'':'')+'</div><div data-strategy-panel="results">'+(experimentComparison?experimentComparisonMarkup(experimentComparison):'')+'</div></fieldset></section>';
}
function experimentCleanOperand(value){return value.kind==='price'?{kind:value.kind,field:value.field}:value.kind==='indicator'?{kind:value.kind,name:value.name}:value.kind==='parameter'?{kind:value.kind,name:value.name,units:value.units}:{kind:'constant',value:value.value,units:value.units};}
function experimentStrategyRequest(){
 if(!experimentExecution)throw new Error('The selected execution and protection contract is not integrated yet.');
 const s=experimentStrategy,rule=value=>({operator:value.operator,atoms:value.atoms.map(atom=>({left:experimentCleanOperand(atom.left),comparison:atom.comparison,right:experimentCleanOperand(atom.right)}))});
 const parameters={};for(const p of s.parameters){if(!p.name||parameters[p.name])throw new Error('Each finite parameter needs a distinct name.');parameters[p.name]={type:p.type,values:p.values.split(',').map(v=>v.trim()).filter(Boolean)};}
 return {version:'declarative-equity-rules-v1',name:s.name,symbol:s.symbol,instrument_id:s.symbol+'.ALPACA',currency:'USD',session:'regular',quantity:experimentCleanOperand(s.quantity),entry:rule(s.entry),exit:rule(s.exit),parameters,execution:{...structuredClone(experimentExecution),limit_price:experimentExecution.limit_price?experimentCleanOperand(experimentExecution.limit_price):null,stop_price:experimentExecution.stop_price?experimentCleanOperand(experimentExecution.stop_price):null,exit_plan:experimentExecution.exit_plan?Object.fromEntries(Object.entries(experimentExecution.exit_plan).map(([key,value])=>[key,experimentCleanOperand(value)])):null}};
}
function experimentRequest(){
 const r=structuredClone(experimentDraft),integer=(value,label)=>{if(String(value).trim()===''||!Number.isSafeInteger(Number(value)))throw new Error('Enter an explicit integer for '+label+'.');return Number(value);};delete r.history_key;delete r.benchmark_history_key;for(const key of ['train_sessions','validation_sessions','gap_sessions','oos_sessions','step_sessions'])r.window[key]=integer(r.window[key],key);
 r.search.seed=integer(r.search.seed,'seed');r.search.max_trials=integer(r.search.max_trials,'maximum trials');r.search.sampler=r.search.mode==='grid'?'GridSampler':'TPESampler';r.search.pruner='NopPruner';r.selection.minimum_closed_trades=integer(r.selection.minimum_closed_trades,'minimum closed trades');
 r.budgets.max_native_runs=integer(r.budgets.max_native_runs,'maximum native runs');for(const kind of ['experiment','trial'])r.budgets[kind+'_seconds']=r.budgets['no_'+kind+'_time_cap']?null:integer(r.budgets[kind+'_seconds'],kind+' deadline');r.scenarios.forEach(s=>s.random_seed=integer(s.random_seed,'scenario seed'));r.currency_basis='declared_simulation_assumption';if(!r.benchmark_history_key)delete r.benchmark_history_key;return r;
}
function experimentLoadStrategy(definition){
 experimentStrategyId=definition.id;experimentStrategyRevision=definition.revision;experimentExecution=structuredClone(definition.execution);experimentStrategy={...structuredClone(definition),parameters:Object.entries(definition.parameters).map(([name,p])=>({name,type:p.type,values:p.values.join(', ')})),time_in_force:definition.execution.time_in_force};experimentDirty=true;experimentStrategyDirty=false;
}
async function experimentAction(action,id){
 if(experimentBusy)return;experimentBusy=true;experimentError='';
 try{
  if(activePage==='strategy')render();
  if(action==='load')experimentSource=await api('/api/evaluations');
  else if(action==='open'){const changed=experimentItem?.id!==id,item=await api('/api/evaluations?id='+encodeURIComponent(id));if(experimentSource&&Number.isSafeInteger(item.revision))experimentSource.revision=item.revision;const saved=experimentSource?.items?.find(row=>row.id===item.id);if(saved)Object.assign(saved,item);if(item.kind==='experiment_comparison')experimentComparison=item;else{experimentItem=item;if(changed){experimentEvent=null;experimentDirty=false;}}}
  else if(action==='event')experimentEvent=await api('/api/evaluations?id='+encodeURIComponent(experimentItem.id)+'&event_id='+encodeURIComponent(id));
  else{
   if(['save-strategy','preview','run'].includes(action)&&!experimentExecution)throw new Error('The selected execution and protection contract is not integrated yet.');
   if(action==='preview'&&experimentStrategyDirty)throw new Error('Save the edited strategy revision before preview.');
   if(action==='run'&&(experimentDirty||experimentItem?.status!=='preview'||experimentSource?.capabilities?.optimizer?.available!==true))throw new Error('Select an unchanged preview and an available optimizer before Run.');
   const request={expected_revision:experimentSource.revision};
   if(action==='save-strategy')Object.assign(request,{action:'save_strategy',strategy_id:experimentStrategyId||undefined,strategy_revision:experimentStrategyRevision||undefined,strategy:experimentStrategyRequest()});
   else if(action==='preview'){strategyView='results';Object.assign(request,{action:'preview_experiment',strategy_id:experimentStrategyId,strategy_revision:experimentStrategyRevision,history_key:experimentDraft.history_key,...(experimentDraft.benchmark_history_key?{benchmark_history_key:experimentDraft.benchmark_history_key}:{}),experiment:experimentRequest(),...(experimentBranch?{parent_id:experimentBranch.id,parent_spec_sha256:experimentBranch.spec_sha256}:{})});}
   else if(action==='compare')Object.assign(request,{action:'compare_experiments',ids:[...experimentCompared]});
   else Object.assign(request,{action:action==='run'?'run_experiment':action==='cancel'?'cancel_experiment':'repeat_experiment',id:experimentItem.id,spec_sha256:experimentItem.spec_sha256});
   const response=await api('/api/evaluations',request);experimentSource=action==='save-strategy'?response:await api('/api/evaluations');
   if(action==='save-strategy'){const rows=response.strategies.filter(row=>row.definition.id===response.saved_strategy_id);if(rows.length!==1)throw new Error('Saved strategy identity is ambiguous; reload saved strategies.');experimentLoadStrategy(rows[0].definition);}
   else if(action==='compare')experimentComparison=response;
   else{experimentItem=response;experimentEvent=null;experimentDirty=false;}
  }
 }catch(error){experimentError=error.message;}finally{experimentBusy=false;if(activePage==='strategy')render();}
 clearTimeout(experimentTimer);if(!experimentError&&activePage==='strategy'&&['queued','running','cancelling'].includes(experimentItem?.status)){const identity=experimentItem.id;experimentTimer=setTimeout(()=>{if(activePage==='strategy'&&experimentItem?.id===identity)experimentAction('open',identity);},5000);}
}
document.addEventListener('input',event=>{
 const path=event.target.dataset.experimentField;if(!path)return;const keys=path.split('.'),section=keys.shift(),strategyField=section!=='request',root=section==='strategy'?experimentStrategy:section==='execution'?experimentExecution:experimentDraft;if(strategyField){experimentStrategyDirty=true;const preview=document.getElementById('experiment-preview');if(preview)preview.disabled=true;}let target=root;while(keys.length>1){const key=keys.shift();target=target[key];}target[keys[0]]=event.target.type==='checkbox'?event.target.checked:event.target.value;experimentDirty=true;const run=document.getElementById('experiment-run');if(run)run.disabled=true;
});
document.addEventListener('change',event=>{
 if(/^strategy\.parameters\.\d+\.name$/.test(event.target.dataset.experimentField||''))for(const select of document.querySelectorAll('select[data-experiment-field$=".name"]')){
  const keys=select.dataset.experimentField.split('.'),root=keys.shift()==='execution'?experimentExecution:experimentStrategy,operand=keys.slice(0,-1).reduce((value,key)=>value?.[key],root);if(operand?.kind!=='parameter')continue;
  select.innerHTML='<option value="">Choose explicitly</option>'+experimentStrategy.parameters.map(parameter=>parameter.name).filter(Boolean).map(name=>'<option value="'+esc(name)+'" '+(operand.name===name?'selected':'')+'>'+esc(name)+'</option>').join('');
 }
 if(event.target.dataset.experimentField==='execution.entry_order_type'){experimentExecution.limit_price=experimentExecution.entry_order_type==='MARKET'?null:experimentExecution.limit_price||{kind:'price',field:'close'};experimentExecution.stop_price=experimentExecution.entry_order_type==='STOP_LIMIT'?experimentExecution.stop_price||{kind:'price',field:'close'}:null;}
 if(event.target.dataset.experimentProtection){const key=event.target.dataset.experimentProtection;experimentExecution.exit_plan||={};if(event.target.checked)experimentExecution.exit_plan[key]={kind:'price',field:'close'};else{delete experimentExecution.exit_plan[key];if(key==='stop_price')delete experimentExecution.exit_plan.stop_limit_price;}if(!Object.keys(experimentExecution.exit_plan).length)experimentExecution.exit_plan=null;experimentStrategyDirty=true;experimentDirty=true;render();}
 if(event.target.dataset.experimentField&&event.target.tagName==='SELECT')render();
 if(event.target.dataset.experimentCompare){event.target.checked?experimentCompared.add(event.target.dataset.experimentCompare):experimentCompared.delete(event.target.dataset.experimentCompare);render();}
 if(event.target.id==='experiment-strategy'){const row=experimentSource.strategies.find(row=>row.definition.id===event.target.value);if(row)experimentLoadStrategy(row.definition);else{experimentStrategyId='';experimentStrategyRevision=null;experimentDirty=true;experimentStrategyDirty=true;}render();}
});
document.addEventListener('click',event=>{
 const b=event.target.closest('[data-experiment-open],[data-experiment-event],[data-experiment-add-atom],[data-experiment-remove-atom],[data-experiment-remove-parameter],[data-experiment-remove-scenario],#experiment-load,#experiment-save-strategy,#experiment-preview,#experiment-run,#experiment-cancel,#experiment-repeat,#experiment-compare,#experiment-add-parameter,#experiment-add-scenario,#experiment-edit-branch');if(!b)return;
 if(b.dataset.experimentOpen){strategyView='results';experimentAction('open',b.dataset.experimentOpen);return;}if(b.dataset.experimentEvent){experimentAction('event',b.dataset.experimentEvent);return;}
 if(b.dataset.experimentAddAtom){experimentStrategy[b.dataset.experimentAddAtom].atoms.push(experimentAtom());}
 else if(b.dataset.experimentRemoveAtom){const [name,index]=b.dataset.experimentRemoveAtom.split(':');experimentStrategy[name].atoms.splice(Number(index),1);}
 else if(b.dataset.experimentRemoveParameter!==undefined)experimentStrategy.parameters.splice(Number(b.dataset.experimentRemoveParameter),1);
 else if(b.dataset.experimentRemoveScenario!==undefined)experimentDraft.scenarios.splice(Number(b.dataset.experimentRemoveScenario),1);
 else if(b.id==='experiment-edit-branch'){strategyTab='strategies';strategyView='setup';const item=experimentItem;if(!item?.preview?.strategy||!item.history_key){experimentError='Exact retained strategy or history selector is unavailable; cannot reconstruct a branch from latest data.';render();return;}experimentLoadStrategy(item.preview.strategy);experimentStrategyId='';experimentStrategyRevision=null;experimentStrategyDirty=true;experimentDraft={...structuredClone(item.preview.request),history_key:item.history_key,benchmark_history_key:item.benchmark_history_key||''};experimentBranch={id:item.id,spec_sha256:item.spec_sha256};}
 else if(b.id==='experiment-add-parameter')experimentStrategy.parameters.push({name:'',type:'integer',values:''});
 else if(b.id==='experiment-add-scenario')experimentDraft.scenarios.push({...experimentScenario(),id:'scenario-'+(experimentDraft.scenarios.length+1)});
 else{experimentAction(b.id.replace('experiment-',''));return;}experimentDirty=true;if(b.dataset.experimentRemoveScenario===undefined&&b.id!=='experiment-add-scenario')experimentStrategyDirty=true;render();
});

async function loadJournal(discard=false){
 if(journalLoading)return;journalLoading=true;
 try{const record=await api('/api/reporting');journalRecord=record;journalError='';journalConflict=false;if(discard){journalDrafts.clear();reportingSettingsDraft=null;}}
 catch(error){journalError=error.message;}
 finally{journalLoading=false;if(['journal','portfolio'].includes(activePage))render();}
}
async function loadJournalCollection(id){
 journalCollection=id;if(!id||journalCollections.has(id)){render();return;}
 if(journalCollectionLoading.has(id))return;
 journalCollectionErrors.delete(id);journalCollectionLoading.add(id);render();
 try{const data=await api('/api/reporting/collections/'+encodeURIComponent(id));if(data.id!==id)throw new Error('History collection identity differs');journalCollections.set(id,data);}
 catch(error){journalCollectionErrors.set(id,error.message);}
 finally{journalCollectionLoading.delete(id);if(['journal','portfolio'].includes(activePage)&&journalCollection===id)render();}
}
async function journalAction(request){
 if(journalLoading||journalConflict)return;journalLoading=true;journalError='';render();
 try{
  const result=await api('/api/reporting',{...request,expected_revision:journalRecord.revision},{timeoutMs:request.action==='collect'?600000:120000});
  if(request.action==='export')download(JSON.stringify(result.export,null,2),'tradingagents-selected-decisions.json','application/json');
  else if(request.action==='export_csv')download(result.csv,result.filename,'text/csv;charset=utf-8');
  else{journalRecord=result;if(request.action==='refresh_methods'){journalCollections.delete(request.collection_id);await loadJournalCollection(request.collection_id);}if(request.action==='settings')reportingSettingsDraft=null;if(request.action==='note')journalDrafts.delete(request.id);if(request.action==='collect'){const item=result.data.collections[0];await loadJournalCollection(item.id);}}
 }catch(error){journalError=error.message;journalConflict=error.status===409;}
 finally{journalLoading=false;render();}
}
function journalNote(item){
 const template=document.createElement('template');template.innerHTML=journalNoteContent(item);
 const panel=template.content.firstElementChild,notes=document.createElement('section');let followup=false;
 for(const node of [...panel.children]){if(node.matches('label[for="decision-assumptions"]'))followup=true;if(followup)notes.append(node);}
 const tab=journalTab==='notes'?'notes':decisionTab;
 const reference=item.research,latest=state.saved_research?.[item.symbol],available=item.research_available===true&&latest?.run_id===reference.run_id&&latest?.revision===reference.revision;
 const research=reference?available?'<button class="button" data-journal-research="'+esc(item.id)+'">Open referenced latest research</button>':'<p>Referenced research unavailable: it has been replaced. Saved terms are unchanged.</p>':'';
 let body=tab==='notes'?notes.innerHTML:tab==='orders'?'<h3>Linked orders and receipts</h3>'+decisionOutcomeMarkup(item):tab==='outcome'?'<h3>Linked position outcomes</h3>'+positionOutcomeLinks([...(item.position_outcome_ids||[]),...(item.command_outcomes||[]).flatMap(command=>command.position_outcome_ids||[])])+decisionOutcomeMarkup(item):panel.innerHTML;
 return '<section class="panel decision-inspector"><div class="panel-header"><h2>'+esc(item.symbol||item.kind)+' · saved decision</h2></div>'+workspaceTabs('decision',tab,[['rationale','Rationale'],['orders','Orders'],['outcome','Outcome'],['notes','Notes']])+'<div class="decision-reading">'+research+body+'</div></section>';
}
