 if(!journalDrafts.has(item.id)){const saved=journalRecord.data.entries[item.id]||{};journalDrafts.set(item.id,{assumptions:saved.assumptions||'',review_date:saved.review_date||'',outcome_notes:saved.outcome_notes||''});}
