 for(const key of ['deep_max_total_tokens','deep_max_output_tokens','quick_max_total_tokens','quick_max_output_tokens'])if(submittedKeys.includes(key))c[key]=String(c[key]??'').trim()?Number(c[key]):null;
 if(c.llm_provider!=='openai_compatible')for(const key of ['deep_max_total_tokens','quick_max_total_tokens'])if(submittedKeys.includes(key))c[key]=null;
 if(['codex','chatgpt'].includes(c.llm_provider))for(const key of ['deep_max_output_tokens','quick_max_output_tokens'])if(submittedKeys.includes(key))c[key]=null;
 for(const key of ['deep_reasoning_effort','quick_reasoning_effort'])if(submittedKeys.includes(key))c[key]=c[key]||null;
 if(!['codex','chatgpt','openai','openai_compatible'].includes(c.llm_provider))for(const key of ['deep_reasoning_effort','quick_reasoning_effort'])if(submittedKeys.includes(key))c[key]=null;
 c.backend_url=submittedKeys.includes('backend_url')&&c.llm_provider==='codex'?null:String(c.backend_url||'').trim()||null;
 try{c.universe=DeskLists.parseSymbols(c.universe).symbols;}
