let drawingSelection='',drawingTool=null,drawingPoints=[],drawingController=null,drawingContext=null,drawingScopeKey='',drawingNotice='',drawingStatuses=[],drawingNewKind='horizontal-line',drawingValueKind='c';
function drawingScope(h){const source=h.source||{};return {symbol:h.symbol,timeframe:h.timeframe||'1Day',context:h.context==='current'?'current':'saved',instrument_id:h.instrument_id??source.instrument_id??h.required_coverage?.provenance?.asset_id??null,currency:h.currency??source.currency??null,unit:'price',provider:h.provider??source.vendor??null,feed:h.feed??source.feed??null,adjustment:h.adjustment??source.adjustment??null,session:h.session??source.session??null};}
