function chartDrawings(h){const scope=drawingScope(h);return Object.values({...workspaceRecord.data.drawings,...Object.fromEntries(drawingDrafts)}).filter(d=>!d.deleted&&drawingPaneMatches(d.scope,scope));}
function selectedDrawing(h){const d=drawingDrafts.get(drawingSelection)||workspaceRecord.data.drawings?.[drawingSelection];return d&&(!d.deleted||drawingDrafts.has(d.id))&&drawingPaneMatches(d.scope,drawingScope(h))?d:null;}
