 const generation=state.store_generation,requestedSymbol=symbol,reference={id:saved.id,revision:saved.revision},current=()=>generation===state.store_generation&&symbol===requestedSymbol&&drawingSelection===saved.id&&drawingContext&&drawingScopeIdentity(drawingScope(drawingContext.h))===drawingScopeIdentity(saved.scope)&&drawingContext.h.key===h?.key&&drawingContext.h.run_id===h?.run_id;
