  ruleDraft={name:option.scope.symbol+' '+option.drawing.kind+' crossing',kind:'drawing',scope:'drawing',symbol:option.scope.symbol,active:false,max_age_seconds:'',drawing_ref:structuredClone(option.drawing_ref),drawing:structuredClone(option.drawing),field:'c',comparison:'cross_above',geometry_policy:'segment',context:option.scope.context==='current'?'current':'research',timeframe:option.scope.timeframe,history_key:h?.key||'',run_id:h?.run_id||'',target_mode:'symbol'};
