async function pollScannerRuns(){
 if(scannerPoll||scannerBusy||document.hidden||activePage!=='markets'||marketsTab!=='scans'||!Object.values(scannerState().data.runs||{}).some(run=>['queued','running','cancelling'].includes(run.status)))return;
 const request={generation:state.store_generation,revision:scannerState().revision};scannerPoll=request;const current=()=>state.store_generation===request.generation&&activePage==='markets'&&marketsTab==='scans';
 try{const response=await api('/api/discovery');if(!current()||scannerBusy||!response.scanner)return;const hadError=!!scannerPollError;scannerPollError='';if(response.scanner.revision<=scannerState().revision){if(hadError)bindDiscovery();return;}const known=scannerState().data.runs||{};if(Object.entries(response.scanner.data.runs||{}).some(([id,run])=>known[id]?.status&&!['queued','running','cancelling'].includes(known[id].status)&&['queued','running','cancelling'].includes(run.status)))return;discoveryMeta={...discoveryMeta,scanner:response.scanner};if(scannerRun&&response.scanner.data.runs[scannerRun.id])scannerRun=response.scanner.data.runs[scannerRun.id];bindDiscovery();}
 catch(error){if(current()&&!scannerBusy&&scannerState().revision===request.revision){scannerPollError='Saved run status could not be updated. Displayed states are from the last scan-library snapshot. Use Refresh saved definitions and jobs. '+error.message;bindDiscovery();}}
 finally{if(scannerPoll===request)scannerPoll=null;}
}
