function bindScannerProgram(){
 const panel=$('saved-data-scans');if(!panel)return;
 const rename=(d,oldName,newName,kind)=>{if(!/^[A-Za-z][A-Za-z0-9_]*$/.test(newName))throw new Error('Use a name starting with a letter and containing letters, digits or underscore.');const p=d.program,group=kind==='input'?p.inputs:p.parameters;if(newName!==oldName&&newName in group)throw new Error('That name already exists.');group[newName]=group[oldName];if(newName!==oldName)delete group[oldName];if(kind==='input'&&p.anchor_input===oldName)p.anchor_input=newName;for(const condition of p.conditions)for(const side of ['left','right'])if(condition[side]?.kind===kind&&condition[side].name===oldName)condition[side].name=newName;};
 panel.querySelectorAll('[data-scan-field]').forEach(control=>{const textDraft=['name','target.symbols'].includes(control.dataset.scanField);if(textDraft)control.addEventListener('input',()=>scannerEdit(d=>scannerSetField(d,control.dataset.scanField,control.value),false));control.addEventListener('change',()=>{if(textDraft)return;scannerEdit(d=>{const path=control.dataset.scanField;scannerSetField(d,path,control.value);if(path.endsWith('.kind')){const parts=path.split('.');parts.pop();let target=d;for(const part of parts)target=target[part];for(const key of Object.keys(target))if(key!=='kind')delete target[key];if(target.kind==='constant')Object.assign(target,{value:'0',units:'scalar'});else if(target.kind==='field')target.field='close';else if(target.kind==='definition')Object.assign(target,{definition:null,output:''});else target.name=Object.keys(target.kind==='input'?d.program.inputs:d.program.parameters)[0]||'';}});});});
 panel.querySelectorAll('[data-scan-rename]').forEach(control=>control.addEventListener('change',()=>scannerEdit(d=>rename(d,control.dataset.scanRename,control.value,'input'))));
 panel.querySelectorAll('[data-scan-rename-parameter]').forEach(control=>control.addEventListener('change',()=>scannerEdit(d=>rename(d,control.dataset.scanRenameParameter,control.value,'parameter'))));
 panel.querySelectorAll('[data-scan-definition]').forEach(control=>control.addEventListener('change',()=>scannerEdit(d=>{const row=scannerFormulaRows().find(r=>analysisRowKey(r)===control.value);d.program.inputs[control.dataset.scanDefinition].value=row?{kind:'definition',definition:{id:row.definition.id,revision:row.definition.revision,sha256:row.sha256},output:scannerComponents(row)[0]||''}:{kind:'definition',definition:null,output:''};})));
 for(const [attribute,group] of [['input','inputs'],['parameter','parameters']])panel.querySelectorAll('[data-scan-remove-'+attribute+']').forEach(button=>button.addEventListener('click',()=>scannerEdit(d=>{delete d.program[group][button.getAttribute('data-scan-remove-'+attribute)];})));
 panel.querySelectorAll('[data-scan-remove-condition]').forEach(button=>button.addEventListener('click',()=>scannerEdit(d=>d.program.conditions.splice(Number(button.dataset.scanRemoveCondition),1))));
 $('scanner-add-program')?.addEventListener('click',()=>scannerEdit(d=>d.program=scannerProgramDefault()));
 $('scanner-add-input')?.addEventListener('click',()=>scannerEdit(d=>{let index=1;while(d.program.inputs['input'+index])index++;d.program.inputs['input'+index]=structuredClone(scannerProgramDefault().inputs.price);}));
 $('scanner-add-parameter')?.addEventListener('click',()=>scannerEdit(d=>{let index=1;while(d.program.parameters['threshold'+index])index++;d.program.parameters['threshold'+index]={value:'0',units:'price'};}));
 $('scanner-add-condition')?.addEventListener('click',()=>scannerEdit(d=>d.program.conditions.push({left:{kind:'input',name:Object.keys(d.program.inputs)[0]||''},comparison:'gt',right:{kind:'constant',value:'0',units:'price'}})));
 $('scanner-sync-json')?.addEventListener('click',()=>scannerEdit(()=>{}));
 $ ('scanner-observation')?.addEventListener('change',event=>{scannerObservation=Number(event.target.value);bindDiscovery();});
 $('scanner-cutoff')?.addEventListener('input',event=>scannerCutoff=event.target.value);
 $('scanner-export')?.addEventListener('click',()=>{const selected=scannerState().data.definitions?.[scannerSelectedId];scannerAction('scan_export',selected?{id:selected.id,revision:selected.revision}:{});});
 $('scanner-import')?.addEventListener('change',async event=>{try{const file=event.target.files?.[0];if(file)await scannerAction('scan_import',{bundle:JSON.parse(await file.text()),expected_revision:scannerState().revision,workspace_revision:workspaceRecord.revision});}catch(error){scannerError=error.message;bindDiscovery();}});
}
