 return '<dl>'+[['Definition revision',definition.revision],['Frozen target mode',definition.target?.mode],['Source mode / feed / adjustment',[c.mode,c.feed,c.adjustment].join(' / ')],['Lookback days',c.lookback_days],['Maximum symbols',c.max_symbols],['Maximum distinct intervals',c.max_intervals],['Maximum provider query pages',c.max_pages],['Maximum explicit provider dispatch operations',c.max_requests],['Stop future dispatch after seconds',c.max_seconds],['Schedule opt-in',s.enabled===true?'Enabled':'Off'],['Cadence / minutes',s.cadence_minutes],['Timezone',s.timezone],['Dispatch session gate',s.session],['Deduplicated attention events',definition.alert===true?'Opted in':'Off']].map(([label,value])=>'<dt>'+esc(label)+'</dt><dd>'+esc(value??'Unavailable')+'</dd>').join('')+'</dl>';
