async function inspectDiscovery(selected,identity=''){
 if(discoveryBusy)return;const token=++discoveryReadToken;discoveryOpen=true;discoveryReading=true;discoveryDetailSymbol=selected||'';if(['overview','markets'].includes(activePage))bindDiscovery();
 try{
  const observation=identity&&discoveryResult?.id===identity?discoveryResult:await api('/api/discovery?'+(identity?'observation='+encodeURIComponent(identity):'symbol='+encodeURIComponent(selected)));
  if(token!==discoveryReadToken)return;
  discoveryResult=observation;discoveryObservationId=observation?.id||'';discoveryError='';
 }catch(error){if(token===discoveryReadToken){discoveryResult=null;discoveryObservationId='';discoveryError=error.message;}}
 finally{if(token===discoveryReadToken){discoveryReading=false;discoveryRestored=discoveryObservationId+':'+discoveryDetailSymbol;persistPreferences();if(['overview','markets'].includes(activePage))bindDiscovery();}}
}
