 const item=proposalInput(),instrument=investorRecord?.instruments?.[symbol],envelope=optionEnvelope(),raw=envelope?.raw,r=DATA.research[raw?.underlying_symbol],runtime=state.nautilus||{},account=runtime.account||{},issue=proposalSessionIssue(item),profiles=optionOrderProfiles(),types=Object.keys(profiles),durations=profiles[item.order_type]||[],limit=['LIMIT','STOP_LIMIT'].includes(item.order_type),stop=['STOP_MARKET','STOP_LIMIT'].includes(item.order_type);
 const predecessors=(runtime.orders||[]).filter(o=>o.symbol===symbol&&['buy_to_open','sell_to_close'].includes(o.position_intent)&&o.extended_hours===false&&['new','partially_filled','done_for_day'].includes(o.status)&&state.investor?.broker_order_actions?.[o.id]?.replace_supported===true);
 return '<section class="proposal-editor"><h3>Manual option premium proposal · '+esc(symbol)+'</h3>'+investorStatus()+'<p>Whole long contracts only · documented single-leg profiles · regular session. Buy to open or sell to close an observed long holding. No linked exits or short opening. Saving is local; exact approval and submission remain separate.</p><p>'+esc(instrument?.limitation||'Current native contract eligibility is checked by preview.')+'</p><p>Observed broker options buying power: '+esc(account.options_buying_power??'Unavailable')+' USD · cash: '+esc(account.cash??'Unavailable')+' USD · account '+esc(account.id||'Unavailable')+' · '+fullTime(runtime.account_at)+'. '+esc(stateErrorMessage||runtime.status!=='connected'||runtime.stale||runtime.account_stale?'Stale or unavailable observation.':'Freshness and account binding are checked during preview.')+' Cash and options buying power are separate; local unsubmitted commitments appear in preview.</p><div class="proposal-fields"><label>Amend an eligible existing option order<select id="proposal-replacement"><option value="">New order</option>'+predecessors.map(o=>'<option value="'+esc(o.id)+'" '+(item.replacement?.order_id===o.id?'selected':'')+'>'+esc(o.side+' '+o.qty+' '+o.symbol+' · '+o.type+' '+o.time_in_force+' · filled '+o.filled_qty+' · '+o.id)+'</option>').join('')+'</select></label>'+(item.replacement?'<p>Exact replacement: contract, intent and order type stay fixed. Review the new total quantity, applicable prices and DAY/GTC duration, approve, then use the existing separate Replace control. Prior fills remain counted from actual predecessor evidence; no native duration update is invented.</p>':'')+'<label>Position intent<select id="option-intent" '+(item.replacement?'disabled':'')+'><option value="">Choose intent</option>'+[['buy_to_open','Buy to open long'],['sell_to_close','Sell to close held long']].map(([v,label])=>'<option value="'+v+'" '+(item.position_intent===v?'selected':'')+'>'+label+'</option>').join('')+'</select></label><label>Whole contracts'+(item.replacement?' · amended total includes prior fills':'')+'<input id="proposal-quantity" inputmode="decimal" value="'+esc(item.quantity)+'"></label><label>Order type<select id="proposal-order-type" '+(item.replacement?'disabled':'')+'><option value="">Choose a supported type</option>'+types.map(type=>'<option '+(type===item.order_type?'selected':'')+'>'+type+'</option>').join('')+'</select></label>'+(!types.length?'<p class="negative">Current supported option profile metadata is unavailable.</p>':'')+(limit?'<label>Limit premium / USD per underlying unit<input id="proposal-limit-price" inputmode="decimal" value="'+esc(item.limit_price||'')+'"></label>':'')+(stop?'<label>Stop trigger premium / USD per underlying unit<input id="proposal-stop-price" inputmode="decimal" value="'+esc(item.stop_price||'')+'"></label>':'')+'<label>Duration<select id="proposal-time-in-force"><option value="">Choose duration</option>'+durations.map(duration=>'<option '+(duration===item.time_in_force?'selected':'')+'>'+duration+'</option>').join('')+'</select></label><p>Regular session only. GTC remains subject to broker expiration and contract expiry. Exact premium × observed deliverable size '+esc(raw?.size??'Unavailable')+' × whole contracts; no stock-price substitution. Precision and native increments are checked by the server without silent rounding.</p>'+optionPriceMeaning(item)+'<label>Optional order note<textarea id="proposal-rationale" rows="3">'+esc(item.rationale||'')+'</textarea></label><label><input id="proposal-link-research" type="checkbox" '+(item.research?'checked':'')+' '+(!r&&!item.research?'disabled':'')+'> Link exact saved underlying analysis ('+esc(raw?.underlying_symbol||'Unavailable')+'); not an option recommendation</label><p>'+esc(item.research?'Linked underlying '+item.research.symbol+' · run '+item.research.run_id+' · revision '+item.research.revision:'No linked underlying research.')+'</p><label>Optional revision note<textarea id="proposal-review-reason" rows="2">'+esc(proposalReason)+'</textarea></label></div><p id="proposal-session-validation" role="alert">'+esc(issue)+'</p><div class="row"><button id="preview-proposal" '+(!instrument?.supported||issue?'disabled':'')+'>Preview exact premium terms</button><button id="save-proposal" '+(!instrument?.supported||issue?'disabled':'')+'>Save local proposal '+(item.id?'revision':'draft')+'</button>'+(item.id?'<button id="reject-proposal">Reject</button><button id="defer-proposal">Defer</button><button id="new-proposal">New proposal</button>':'')+'</div><div id="proposal-impact">'+impactMarkup(proposalPreviews.get(proposalKey(symbol)))+'</div></section>'+optionInstructionsMarkup(symbol);
