 return '<h3>Exact terms · '+esc(terms.side)+' '+esc(terms.quantity)+' '+esc(terms.symbol)+'</h3><p>'+esc(terms.order_type)+' '+esc(terms.limit_price||'No fixed market price')+(terms.stop_price?' · stop trigger USD '+esc(terms.stop_price):'')+' · '+esc(terms.time_in_force||'DAY')+' · '+esc(terms.session==='extended'?'Extended sessions':(terms.session??'regular')==='regular'?'Regular session':'Unknown session')+' · account '+esc(terms.account_id||'Unavailable')+'</p>'+(terms.order_type==='TRAILING_STOP_MARKET'?'<p><strong>Approved initial trail: '+esc(terms.trail_price!=null?'USD '+terms.trail_price:terms.trail_percent+'%')+'</strong>. This is a distance, not the broker high-water mark or current moving stop. Alpaca owns the regular-session trigger; market execution price is not guaranteed.</p>':'')+optionImpactMarkup(proposal)+(terms.asset_class==='us_option'?optionPriceMeaning(terms):'')+exitPlanMarkup(terms)+(terms.price_references?.length?'<details><summary>Exact historical price references and normalization</summary><pre>'+esc(JSON.stringify(terms.price_references,null,2))+'</pre></details>':'')+(terms.replacement?'<p>Replace broker order '+esc(terms.replacement.order_id)+' · total quantity includes '+esc(terms.replacement.filled_quantity)+' already filled shares · exact predecessor version '+esc(terms.replacement.order_version)+'</p>':'')+'<p>'+esc(terms.rationale||'No human rationale entered')+'</p><p>'+esc(terms.research?'Linked '+terms.research.report_key+' · run '+terms.research.run_id+' · revision '+terms.research.revision+' · SHA-256 '+terms.research.result_sha256:'Human proposal · no linked research')+'</p><dl>'+[['Existing quantity','existing_quantity'],['Proposed resulting quantity','resulting_quantity'],['Estimated principal / USD','estimated_principal'],['Cash change before fees / USD','estimated_cash_change_before_fees'],['Cash after known commitments before fees / USD','estimated_cash_after_commitments_before_fees'],['Current equity / USD','equity'],['Estimated position value / USD','position_value_estimate'],['Source long market value / USD','account_long_market_value'],['Fees / USD','fees']].map(([label,key])=>'<dt>'+label+'</dt><dd>'+esc(impact[key]??'Unavailable')+'</dd>').join('')+'</dl><p>'+esc(impact.fee_disclosure||'Actual fees are not sourced; a reviewed fee ceiling is a bound, not an actual fee.')+'</p><p>Estimate basis: '+esc(impact.price_basis)+' · account observed '+fullTime(impact.account_at)+' · market event ns '+esc(impact.price_event_ns||'Unavailable')+'</p><details><summary>Known working-order commitments</summary><pre>'+esc(JSON.stringify(impact.open_order_commitments,null,2))+'</pre></details><h3>Source limitations and review conditions</h3><ul>'+impact.conditions.map(c=>'<li>'+esc(c==='Fees are not sourced; after-fee cash impact is unknown'&&number(reviewedFees)!==null&&number(reviewedFees)>=0?'Actual fees remain unknown; review uses the explicit USD '+reviewedFees+' fee ceiling, not an assumed actual fee.':c)+'</li>').join('')+'</ul><details id="proposal-policy-scenarios"><summary>Current / pending / proposed policy calculations</summary><pre>'+esc(JSON.stringify(proposal.risk_evaluation?.policy_scenarios||{unavailable:'No server policy assessment recorded'},null,2))+'</pre></details><p>These are observation-based estimates. Exact saved-revision approval review appears separately.</p><a href="#orders">Review orders and submission status</a>';
