 const holding=DATA.holdings.find(p=>p.symbol===item.symbol);
 if(item.side!=='SELL'||!holding||String(holding.side).toLowerCase()!=='long'||!(Number(holding.qty)>0))return 'Trailing stops require an existing long holding and SELL side. BUY trailing stops are unavailable.';
 if(item.replacement||item.exit_plan)return 'Trailing stops are standalone orders. Linked exits and trailing replacements are unavailable.';
 if(!/^(?:0|[1-9]\d{0,17})(?:\.0{1,9})?$/.test(item.quantity)||!/[1-9]/.test(item.quantity))return 'Enter a positive whole-share quantity. Fractional trailing stops are unavailable; no quantity is selected automatically.';
