 const fields=['trail_price','trail_percent'].filter(key=>item[key]!=null&&item[key]!=='');
 if(fields.length!==1)return 'Enter exactly one initial trail: a USD distance or a percentage.';
 const key=fields[0],value=String(item[key]),pattern=key==='trail_price'?/^\d{1,12}(?:\.\d{1,2})?$/:/^\d{1,12}(?:\.\d{1,9})?$/;
