 const body=document.createElement('div');body.className='ticket-body';ticket.append(body);const panes={};for(const name of names){const pane=document.createElement('section');pane.dataset.ticketStep=name;panes[name]=pane;body.append(pane);}
 const entry=panes.Entry||panes.Exits;entry.append(panel);if(exit)panes.Exits.append(exit);const impact=panel.querySelector('#proposal-impact');if(impact)panes.Review.append(impact);if(approval)panes.Review.append(approval);
