 const select=name=>{ticketSteps.set(symbol,name);for(const [key,pane]of Object.entries(panes))pane.hidden=key!==name;for(const button of nav.querySelectorAll('button'))button.setAttribute('aria-pressed',String(button.dataset.step===name));for(const button of footer.children){const review=['evaluate-approval','record-approval'].includes(button.id)||button.hasAttribute('data-approval-submit')||button.hasAttribute('data-command-submit');button.hidden=review&&name!=='Review';}};
 for(const name of names){const button=document.createElement('button');button.type='button';button.dataset.step=name;button.textContent=name;button.onclick=()=>select(name);nav.append(button);}select(names.includes(step)?step:names[0]);
