function bindAttention(root){
 root.addEventListener('toggle',e=>{if(e.target.id==='attention-workspace')attentionOpen=e.target.open;},true);
 root.addEventListener('input',e=>{
  const fields={'alert-name':'name','alert-kind':'kind','alert-scope':'scope','alert-symbol':'symbol','alert-threshold':'threshold','alert-age':'max_age_seconds','alert-proposal':'proposal_id','alert-condition':'condition','alert-operator':'operator','alert-target-mode':'target_mode','alert-watchlist':'watchlist_id'};
  if(e.target.id.startsWith('alert-drawing-')){const key=e.target.id.slice('alert-drawing-'.length);ruleDraft[key==='candidate'?'drawing_candidate':key]=e.target.value;attentionDirty=true;}
  if(e.target.id.startsWith('alert-indicator-')){ruleDraft[e.target.id.slice(16)]=e.target.value;attentionDirty=true;}
  if(fields[e.target.id]){ruleDraft[fields[e.target.id]]=e.target.value;if(e.target.id==='alert-target-mode')ruleDraft.target=null;if(e.target.id==='alert-kind'&&['indicator','drawing'].includes(e.target.value))ruleDraft.scope=e.target.value;attentionDirty=true;}
  const draft=reviewDrafts.get(reviewKey(symbol));if(draft){if(e.target.id==='research-disposition')draft.disposition=e.target.value;if(e.target.id==='research-review-notes')draft.notes=e.target.value;}
 });
 root.addEventListener('change',e=>{if(['alert-kind','alert-target-mode','alert-indicator-context','alert-drawing-context'].includes(e.target.id))render();if(e.target.id==='alert-active'){ruleDraft.active=e.target.checked;attentionDirty=true;}if(e.target.id==='research-priority')reviewDrafts.get(reviewKey(symbol)).prioritize=e.target.checked;});
 root.addEventListener('click',async e=>{
  const open=e.target.closest('[data-attention-occurrence]'),ack=e.target.closest('[data-ack-attention]'),edit=e.target.closest('[data-edit-rule]'),action=e.target.closest('[data-rule-action]');
  if(e.target.id==='bind-alert-drawing'){
   const option=attentionRecord.drawing_options?.find(o=>o.drawing_ref.drawing_id+'/'+o.drawing_ref.revision+'/'+o.drawing_ref.geometry_sha256===(ruleDraft.drawing_candidate??(ruleDraft.drawing_ref?ruleDraft.drawing_ref.drawing_id+'/'+ruleDraft.drawing_ref.revision+'/'+ruleDraft.drawing_ref.geometry_sha256:'')));
   if(!option){attentionError='Choose a current eligible saved numeric drawing revision; no historical/latest substitution is performed.';render();return;}
   const context=option.scope.context==='current'?'current':'research';if(ruleDraft.context!==context||ruleDraft.timeframe!==option.scope.timeframe){ruleDraft.history_key='';ruleDraft.run_id='';}
   Object.assign(ruleDraft,{kind:'drawing',scope:'drawing',symbol:option.scope.symbol,drawing_ref:structuredClone(option.drawing_ref),drawing:structuredClone(option.drawing),field:ruleDraft.field||'c',comparison:ruleDraft.comparison||'cross_above',geometry_policy:ruleDraft.geometry_policy||'segment',context,timeframe:option.scope.timeframe,target:{mode:'symbol',symbol:option.scope.symbol},target_mode:'symbol',watchlist_id:''});
   attentionDirty=true;attentionError='Chosen saved geometry is bound in this draft. Save the rule revision explicitly to establish its new baseline; acknowledgment/pause do not rearm it.';render();return;
  }
  if(open)openAttentionEvidence(open.dataset.attentionOccurrence);
  if(ack){const occurrence=attentionRecord.observations.data.occurrences[ack.dataset.ackAttention];attentionAction({action:'acknowledge',id:occurrence.id,occurrence_revision:occurrence.revision});}
  if(edit){alertsTab='Rules';const rule=attentionRecord.data.rules[edit.dataset.editRule];ruleDraft={...structuredClone(rule),...rule.parameters,target_mode:rule.target?.mode||'symbol',watchlist_id:rule.target?.watchlist_id||'',atomIndex:rule.atoms?0:undefined};attentionOpen=true;render();}
  if(action)attentionAction({action:action.dataset.ruleAction,id:action.dataset.ruleId});
  if(e.target.id==='save-alert-rule')attentionAction({action:'save',id:ruleDraft.id,name:ruleDraft.name,symbol:ruleDraft.symbol.toUpperCase(),active:ruleDraft.active,atoms:alertAtoms(),operator:ruleDraft.operator||'ALL',target:{mode:alertAtoms().some(a=>a.kind==='drawing')?'symbol':ruleDraft.target?.mode||ruleDraft.target_mode||'symbol',symbol:ruleDraft.symbol.toUpperCase(),watchlist_id:ruleDraft.watchlist_id||ruleDraft.target?.watchlist_id}});
  if(e.target.id==='add-alert-atom'){const values=ruleDraft.atoms||[];if(Number.isInteger(ruleDraft.atomIndex))values[ruleDraft.atomIndex]=alertAtom();else if(values.length<16)values.push(alertAtom());else{attentionError='Use at most 16 conditions';render();return;}ruleDraft.atoms=values;delete ruleDraft.atomIndex;for(const key of ['kind','scope','threshold','max_age_seconds','proposal_id','condition'])ruleDraft[key]='';attentionDirty=true;render();}
  const atomEdit=e.target.closest('[data-edit-alert-atom]'),atomRemove=e.target.closest('[data-remove-alert-atom]');
  if(atomEdit){const i=Number(atomEdit.dataset.editAlertAtom),atom=ruleDraft.atoms[i];Object.assign(ruleDraft,atom,atom.parameters,{atomIndex:i});render();}
  if(atomRemove){ruleDraft.atoms.splice(Number(atomRemove.dataset.removeAlertAtom),1);delete ruleDraft.atomIndex;for(const key of ['kind','scope','threshold','max_age_seconds','proposal_id','condition'])ruleDraft[key]='';attentionDirty=true;render();}
  if(e.target.id==='save-research-review'){const r=researchFor(symbol);attentionAction({action:'review',symbol,run_id:r.run_id,research_revision:r.revision||0,...reviewDrafts.get(reviewKey(symbol))});}
  if(e.target.id==='reload-attention'){try{attentionRecord=await api('/api/attention');state.attention=attentionRecord;attentionDirty=false;attentionError='';attentionConflict=false;ruleDraft={name:'',kind:'',scope:'',symbol:'',threshold:'',max_age_seconds:'',proposal_id:'',condition:'',active:false};render();}catch(error){attentionError=error.message;render();}}
 });
}
