function decisionOutcomeMarkup(item){
 const links=(item.decision_links||[]).map(id=>'<button class="link-button" data-journal-decision="'+esc(id)+'">'+esc(id)+'</button>').join(' · ');
 return '<p>'+links+'</p>'+positionOutcomeLinks([...(item.position_outcome_ids||[]),...(item.command_outcomes||[]).flatMap(command=>command.position_outcome_ids||[])])+(item.command_outcomes||[]).map(c=>'<article><h3>Command '+esc(c.command_id)+'</h3><p>Broker outcome: '+esc(c.broker_outcome)+' · filled '+esc(c.filled_quantity)+' · native application: '+esc(c.native_application)+'</p>'+commandReceiptLinks(c)+'<p>Broker IDs '+esc(c.broker_order_ids.join(', ')||'None recorded')+' · fills '+esc(c.fill_ids.join(', ')||'None recorded')+'</p><details><summary>Command approval, exact terms, broker receipts and historical native receipts</summary><pre>'+esc(JSON.stringify(c,null,2))+'</pre></details></article>').join('')+(item.execution_plans?.length?'<details><summary>Non-atomic basket completion and paused legs</summary><pre>'+esc(JSON.stringify(item.execution_plans,null,2))+'</pre></details>':'');
}


function commandReceiptLinks(command){
 const found=new Map();
 function walk(value){if(!value||typeof value!=='object')return;if(value.path&&/^[0-9a-f]{64}$/.test(value.sha256||''))found.set(value.sha256,value.path);for(const child of Object.values(value))if(child&&typeof child==='object')walk(child);}
 walk(command.native_receipts);walk(command.timeline);
 return [...found].map(([sha,path])=>'<p><a href="/api/commands/'+encodeURIComponent(command.command_id)+'/receipts/'+sha+'" target="_blank" rel="noopener">Open saved receipt '+esc(path)+'</a> · SHA-256 '+esc(sha)+'</p>').join('');
}
